combobox.script:
                    function onInit()
                        if super and super.onInit then
                            super.onInit();
                        end
                        clear()
                        ChatlogExplorer.parseChatLogs()
                        for i, _ in ipairs(ChatlogExplorer.tChatLogs) do
                            add(ChatlogExplorer.tChatLogs[i][1], ChatlogExplorer.tChatLogs[i][1], false)
                        end
                    end

                    function onValueChanged()

	                    local sCurValue = getSelectedValue();
                        window.list.closeAll();
	                    local w = nil;
	                    local sColor = "";
	                    local bLink = false;
	                    local sText = "";
	                    for i, _ in ipairs(ChatlogExplorer.tChatLogs) do
		                    if ChatlogExplorer.tChatLogs[i][1] == sCurValue then
			                    for _, y in ipairs(ChatlogExplorer.tChatLogs[i]) do
				                    w = window.list.createWindow();
				                    sColor, bLink, sText = ChatlogExplorer.extractDetails(y);
				                    w.chatlog_text.setValue(sText);

				                    if bLink then
					                    sColor = "FF0000FF";
				                    end

                                    if sColor == "" then
                                        sColor = "FF000000";
                                    end

                                    w.chatlog_text.setUnderline(bLink);
				                    w.chatlog_text.setColor(sColor);
				                    sColor = "";
				                    bLink = false;
				                    sText = "";
			                    end
		                    end
	                    end
                    end
